    stealCaught: "\"도둑이야!\" 주인이 소리친다. 어디선가 대식자가 냄새를 맡았다.",
    stealSlip: "(손이 먼저 움직였다 — {item}, 어느새 품 안으로.)",
    hwangFury: ["…방금 뭐 하셨어요?", "내려놓으세요. …아니에요, 됐어요. 그냥 가져가세요. 그리고 나가 주세요. 다시는 그 손으로 제 진열장 만지지 마세요.", "(미스 황이 문을 가리킨다. 손이 떨리고 있다. 횃대의 앵무새가 날개를 크게 펼친다.)"],
    hwFury: ["…여기서요? 지옥에서 제 물건을요?", "웃기지도 않네요. 가져가세요. 그리고 나가세요, 지금요. 다음엔 그 손목을 저울에 달아 드릴게요.", "(황혼이 등불을 내려놓는다. 커다란 앵무새가 목을 길게 빼고 쉭쉭 소리를 낸다.)"],
    hwangGrudge: "…또 왔네요. 이번엔 손 보이는 데 두세요. 계속 볼 거예요.",
