    sleeperSub: "길에서 편히 자는 중",
    sleeperLines: ["음냐… 오 분만…", "zzz…", "깨우지 마요… 걱정 없는 꿈이에요…", "…침대 공짜예요… 옆에 거 쓰세요…"],
    heavenVendorCalls: ["공짜예요! 따끈할 때 드세요!", "한 그릇 하고 가요, 돈 안 받아요!", "오늘 망고 정말 달아요!", "배 안 고파도 괜찮아요, 맛으로 먹는 거예요!"],
    preachBack: ["아 좀! 간다고요!", "왜 때려요, 천국에서!", "알았어요, 알았어!"],
