    maskCalls: ["마스크 있어요…", "검은 거요. 하나에 천팔백사십오.", "재 먹지 말고 하나 써요."],
    maskLook: "헝클어진 갈색 머리, 해진 갈색 숄 아래 검붉은 원피스. 등에는 국방색 연료통 두 개가 끈에 매여 있고, 어깨 너머로 분사관이 삐죽 나왔다. 팔에 건 등나무 바구니에는 검은 마스크가 수북하다. 뺨의 그을음은 닦을 생각이 없어 보인다.",
    maskNoFight: "때려 봤자 마스크밖에 안 나와요. 그것도 돈 내야 하고요.",
    maskGreet: ["…마스크 사러 왔어요? 아니면 그냥 구경?", "여기 재는 폐에 쌓여요. 오래 있을 거면 하나 써요."],
    maskPitch: "얼굴 반을 가리면 사람들이 덜 쳐다봐요. 덜 쳐다보면 손이 좀 편해지죠. 위로 올라가도 벗을 필요 없어요. 이건 따라가요.",
    flamerPitch: "이건 팔려고 멘 거 아니에요. 그래도 노전만 있으면 내려 줄게요. 하루에 오 분. 그 이상은 통이 못 버텨요. 날이 바뀌면 다시 차고요.",
    maskBuy: "산다 ({n})",
    maskNo: "다시 생각해 볼게",
    maskPoor: "노전이 모자라요. 바구니는 외상을 몰라요.",
    maskSold: "잘 어울려요. 눈만 보이니까 오히려 무섭네.",
    flamerSold: "무거워요. 통부터 받쳐요. 오 분이에요. 꼭이요.",
