    passerFight: ["건드리지 마!", "그래, 해 보자.", "나도 손이 있어.", "너만 무기가 있는 줄 아니?", "같이 죽을까?", "기다려. 죽여줄게.", "어디서 시비야!", "오늘 사람 잘못 골랐다.", "참으려고 했는데.", "내가 만만해 보여?", "그냥 맞고만 있을 줄 알았어?", "후회하게 해 줄게."],
    passerDraw: ["(품에서 칼을 꺼낸다)", "이것까진 안 꺼내려 했는데.", "가까이 오면 찌른다."],
