    cageName: "보관 우리",
    cageLine: "큰 짐승을 가두던 쇠창살 우리. 잡동사니 사이에 누군가의 칼이 기대 서 있다. 맡기는 건 공짜, 꺼낼 때는 수수료.",
    cageLineHell: "유황 냄새 밴 쇠우리. 맡기는 건 공짜, 꺼낼 때는 노전으로 수수료.",
