    parrotFee: ["수수료 내야지.", "돈을 내.", "공짜는 없어."],
    cagePay: "수수료 {p} 내기",
    cageNo: "그만두기",
    parrotBroke: ["(앵무새가 고개를 돌린다.) …돈을 내.", "(앵무새가 빗장 위에 발을 올려놓는다.) 없으면 못 줘."],
    cageOpened: "(앵무새가 부리로 빗장을 들어 올린다. 쇠문이 끼익 열린다.) {item} {n}개를 꺼냈다.",
