    gkQ: ["당신은 누구입니까", "천국과 지옥은 어떤 사이입니까", "신은 있습니까", "지옥의 주인은 누구입니까", "어떻게 해야 죽을 수 있나요", "어떻게 하면 다시 태어납니까", "여기서 무엇을 조심해야 합니까", "물러나겠습니다"],
    gkA: [["나는 염소대왕이다."], ["그냥 비즈니스적인 관계."], ["너는 신을 믿나?", "나는 무신론자다."], ["너 따위가 그걸 왜 묻지?", "죽고서도 또 죽고 싶은가?", "내가 감히 거론할 수 없는 분이다."], ["넌 이미 죽었는데 그걸 왜 물어?"], ["올라가라.", "층마다 속죄의 회당에 노전을 바쳐라. 다 채우면 한 층 위.", "1층 골목 끝이 지옥 로비다. 서류는 파샤르가 만든다."], ["배고픔, 빚, 착한 척하는 놈.", "장비는 부러지기 전에 대장간에 맡겨라."]],
