    civ: {"office": {"name": "회사원", "look": "구김 간 셔츠에 사원증 목걸이. 한 손은 늘 휴대폰이다.", "jab": ["아, 바빠 죽겠는데.", "(통화 중) 네, 네, 지금 이상한 사람이 앞에 있어서요.", "시간 없어요. 비켜요.", "(시계를 보고 한숨) 이런 사람들 때문에 늦는다니까.", "부딪혔으면 사과를 해야지."]}, "student": {"name": "학생", "look": "교복 차림. 가방끈을 한쪽 어깨에만 걸쳤다.", "jab": ["(친구에게 속삭인다) 야, 저 사람 봐.", "저 옷 뭐야, 진짜?", "(키득거리며 지나간다)", "찍어서 올려야지.", "꼰대 냄새 난다."]}, "auntie": {"name": "아주머니", "look": "꽃무늬 블라우스에 장바구니. 목소리가 크다.", "jab": ["어머, 젊은 사람이 왜 이러고 다녀.", "우리 애는 안 저러는데.", "(장바구니로 당신을 툭 친다)", "줄 서요, 줄! 새치기하지 말고.", "말세야, 말세."]}, "elder": {"name": "노인", "look": "흰머리에 낡은 카디건. 지팡이 끝이 닳았다.", "jab": ["우리 때는 말이야…", "요즘 것들은 인사를 몰라.", "(땅을 탕 친다) 쯧쯧.", "그렇게 살면 못 써.", "뭘 쳐다봐, 어른이 말하는데."]}, "worker": {"name": "노동자", "look": "먼지 앉은 작업복에 안전모. 손에 렌치를 쥐었다.", "jab": ["어이, 비켜. 짐 지나간다.", "일 안 하고 뭐 해.", "(침을 퉤 뱉는다)", "손이 그렇게 고와서야.", "건드리지 마라. 오늘 기분 안 좋다."]}, "bouncer": {"name": "클럽 경비", "look": "목이 굵다. 검은 티셔츠가 팽팽하게 당겨져 있다.", "jab": ["여긴 너 같은 애 오는 데 아니야.", "(팔짱을 끼고 길을 막는다)", "돌아가.", "한 번만 더 쳐다보면…", "웃어? 지금 웃었어?"]}, "rider": {"name": "오토바이 기사", "look": "번호가 찍힌 주황 조끼. 헬멧을 팔에 걸고 있다.", "jab": ["(경적을 빵빵 울린다)", "보도로 다녀, 보도로!", "어휴, 길 한가운데서 뭐 해.", "(아슬아슬하게 스치고 지나간다)", "치여도 내 탓 아니다."]}, "vendor": {"name": "노점상", "look": "기름 묻은 앞치마. 허리춤에 식칼이 꽂혀 있다.", "jab": ["안 살 거면 만지지 마.", "구경만 할 거면 저리 가.", "(당신 뒤의 손님을 먼저 받는다)", "돈 없어 보이는데.", "가격? 너한텐 두 배."]}},
    jab: ["아 좀 비켜요. 길 막지 말고.", "냄새 나지 않아요? …아, 당신이구나.", "(위아래로 훑어본다) 흠.", "어디서 굴러먹다 왔대.", "저기요, 등에 뭐 묻었어요. …농담이에요.", "(코를 막고 지나간다)", "눈 깔아요. 뭘 봐요.", "(혀 차는 소리) 쯧.", "인생 참 쉽게 사네.", "(휴대폰으로 당신을 찍는다)"],
