    xchGreet: ["(붉은 꼬리가 바닥을 쓸고 지나간다.) 이승 돈을 들고 오셨군. 여기선 그냥 종잇조각이야. 그래도 내가 받아 주지.", "어서 와, 떨어진 손님. 통장은 아직 이승에 남아 있지? 그걸 노전으로 바꿔 주지. 아주 조금."],
