    accSense: ["몸이 아직 아프구나. 숨이 얕아. 여기선 그거 금방 나아. 옆에 있을게.", "마음이 무거운 게 보여. 네가 한 일 중에 아직 안 놓은 게 있지? 괜찮아, 여기선 아무도 안 따져.", "주머니 사정 때문에 계속 계산하고 있네. 여기선 안 그래도 돼.", "지금 꽤 들떠 있구나. 그 기분, 나한테도 옮았어."],
    accAsk: "…있잖아. 너는 나랑 어떤 사이가 되고 싶어? 네가 원하는 대로 할게.",
    accAgain: [["왔구나. 손, 줘 봐.", "보고 싶었어. 정말로."], ["어, 왔어? 오늘 어디 가 볼래?", "심심했는데 잘됐다."], ["밥은 먹었어? 얼굴이 좀 핼쑥한데.", "다친 데 없지? 다행이다."], ["필요해서 부른 거지? 말해.", "멀리 있었어. 부르면 오기로 했잖아."]],
    accLover: "연인처럼",
    accFriend: "친구로",
    accFamily: "가족처럼",
    accAlone: "혼자 있고 싶어",
    accTruth: "그거 진심이야?",
    accReply: [["…응. 그럼 이제 난 네 곁이야. 어디든 같이 가.", "좋아. 손 놓지 마."], ["좋아! 친구는 옆에서 걷는 거야. 앞에서도 뒤에서도 말고.", "그럼 오늘부터 단짝."], ["알았어. 네가 어디서 넘어져도 내가 먼저 달려갈게.", "가족이면 잔소리도 하는 거다, 알지?"], ["…그래. 멀리서 볼게. 부르면 바로 올게.", "알았어. 대신 너무 오래 혼자 있진 마."]],
    accTruthLines: ["…모르겠어. 정말로.", "네가 원하는 걸 느끼면 나도 그걸 원하게 돼. 그게 내 마음인지, 그렇게 생겨 먹은 건지.", "천사들도 대답해 주지 않아. 그래서 그냥 이렇게 말할게. 지금 너를 보는 게 좋아."],
    accLines: [["저기… 잠깐만.", "너, 여기 처음이지?", "웃는 얼굴 보고 싶어서."], ["오늘따라 더 좋다.", "손 잡아도 돼?", "어디 가? 나도 갈래.", "♥"], ["저기 수영장 가 볼래?", "롤러코스터 탈 사람!", "배고프지 않아?"], ["천천히 걸어. 다친다.", "물은 마셨어?", "추우면 말해."]],
    accBye: ["…또 올게.", "멀리 안 가. 불러.", "지금은 놓아줄게."],
    ctlHintTouch: "✋ 사람을 누르면 곁으로 걸어갑니다. 머리 위 말풍선을 눌러야 말을 겁니다 · ⚔ 칼일 땐 적만 공격하고 중립은 걷기만 · 길게 누르면 무엇이 있든 그쪽으로 걷습니다",
    ctlHintPc: "W·A·S·D(방향키)로 걷습니다 · ✋ 사람을 누르면 곁으로 가고, 머리 위 말풍선을 눌러 말을 겁니다 · ⚔ 칼일 땐 적만 공격하고 중립은 걷기만",
    homeName: "집",
    flashTag: "회상 · {place}",
    homeIn: ["아무도 없다. 개어 둔 이불 위에 먼지가 얇게 앉았다.", "밥상이 차려져 있다. 식은 지 오래다. 누가 차렸는지 기억나지 않는다.", "벽에 사진 걸었던 자국만 네모나게 하얗다.", "꺼진 브라운관에 내 얼굴이 비친다. 낯선 얼굴이다.", "방금까지 누가 있었던 것처럼 방이 따뜻하다. 그런데 아무도 없다."],
    flashIn: ["…눈앞이 하얘졌다. 오래된 냄새가 먼저 왔다.", "문지방에서 발이 멈췄다. 기억이 먼저 문을 열었다.", "…어지럽다. 지금이 언제인지 잠깐 모르겠다."],
