    ysOwner: "원장",
    ysHello: ["어서 오세요. 잠깐만 앉아 계세요, 이분 거의 끝났어요.", "오셨어요? 오늘은 어떻게 해 드릴까요?", "문 좀 닫아 주실래요? 바람이 들어와서요. …네, 머리 하시게요?"],
