    ysBye: "괜찮아요",
    ysBack: "다시 생각해 볼게요",
    ysPoor: "어머, 돈이 좀 모자라시네. 다음에 와요.",
    ysCutDone: ["됐다. 거울 한번 보세요.", "어때요, 훨씬 가벼워 보이죠?"],
    ysDyeDone: ["색 잘 나왔네요. 며칠은 머리 감을 때 물 빠져요.", "이 색 잘 어울리세요. 진짜로요."],
    ysYunae: ["유내요? …아뇨, 처음 들어 보는 이름이에요.", "간판이요? 제가 들어올 때부터 저 이름이었어요. 바꿀까 하다가, 동네 분들이 다 그 이름으로 찾아오셔서 그냥 뒀어요.", "글쎄요. 이 동네 사람이면 제가 알 텐데요. 연락처 같은 것도 없어요."],
    ysYunaeMore: ["그분 찾으시는 거예요? 미안해요. 정말 몰라요.", "가끔 그 이름 묻는 분이 있어요. 다들 소파에 잠깐 앉았다가, 머리는 안 하고 가시더라고요.", "거울 보고 계시네. 다들 그 자리에서 거울을 한참 봐요. 뭐가 있는 것도 아닌데.", "아는 사람이었으면 좋았을 텐데. 이름이 예쁘잖아요, 유내."],
    ysInFirst: "거울도, 의자도 그대로다. 가위를 든 사람만 다르다.",
    ysIn: ["머리 말리개가 여전히 웅웅거린다.", "익숙한 샴푸 냄새. 낯선 목소리.", "탁자 위 잡지의 날짜가 맞지 않는다."],
