    setSfxVol: "효과음 크기",
    homeNo: ["가기 싫다.", "이제 남의 집인 것 같다.", "엄마는 어디 있을까.", "할아버지가 어디 갔지?", "문고리가 차갑다. 오늘은 아니다.", "아까 그 냄새가 아직 골목에 남아 있다.", "누가 먼저 다녀간 것 같다.", "불 꺼진 창을 한참 올려다봤다."],
    cageKind: "앵무새가 배부르다 — 비싼 물건은 수수료 2% 덜",
    ywAloneOk: "알았어요. 이번엔 멀리서 볼게요. 다음에 오면 또 곁에 있을 거예요.",
    ywCatchUp: ["기다려요! 그렇게 빨리 가시면…", "휴, 찾았다.", "날개가 있어서 다행이에요.", "길 잃으면 안 돼요. 여기 넓어요."],
    noeulName: "노을",
    noeulSub: "천국의 신앙 감시자 · 긴 장검",
    noeulFirst: ["노을입니다. 천국의 신앙 감시자.", "천사들의 웃음과 영혼들의 기도를 셉니다. 숫자가 맞지 않으면 제가 찾아갑니다.", "…왜 그렇게 봅니까. 나를 아는 사람처럼."],
    noeulSuspect: ["황색날개가 당신을 너무 오래 데리고 다니는군요. 규정보다 깁니다.", "기도하는 척은 누구나 합니다.", "당신 눈빛은 아직 아래쪽 사람의 것입니다.", "그 천사는 규정보다 오래 웃습니다. 알고 있었습니까?", "황색날개는 아래 세상 어느 가게 여자와 얼굴이 같다더군요. 우연이라고 생각합니까?", "어디서 왔는지 묻는 게 아닙니다. 무엇을 버리고 왔는지 묻는 겁니다.", "웃지 마십시오. 여기서 웃음은 검사 대상입니다.", "당신, 어디선가 본 얼굴입니다. 기억나지 않는 게 더 수상하군요."],
    noeulSuspect2: ["황색날개에게 전하십시오. 다음 점검은 예고 없이 합니다.", "기록은 지우지 않습니다. 고칠 뿐입니다.", "…아닙니다. 아무것도."],
    noeulOrder: ["종교행사에 참석하십시오. 지금입니다.", "행사 시간입니다. 당신 이름이 명단에 없습니다. 가십시오.", "기도는 혼자 하는 게 아닙니다. 행사장으로."],
    noeulRefuse: "지금은 안 갑니다",
    noeulNoted: ["기록해 두겠습니다.", "그 대답도 셉니다.", "좋습니다. 다음엔 묻지 않겠습니다."],
    noeulCalls: ["…지켜보고 있습니다.", "황색날개, 또 규정 위반이군.", "기도 시간입니다.", "저 영혼은 아직 아래 냄새가 납니다.", "웃음 하나, 기도 셋.", "칼은 겁주려고 든 게 아닙니다."],
    zooDemon: "우리 속의 악마",
    zooBeast: "우리 속의 괴물",
    zooSinner: "죄 지은 인간",
    zooDemonSub: "지옥에서 데려왔다. 먹이를 주지 마시오.",
    zooBeastSub: "지옥 층의 괴물. 철창에 손을 넣지 마시오.",
    zooSinnerSub: "죄 지은 인간. 관람 시간: 영원.",
    zooSinnerCalls: ["여기서 꺼내 줘요.", "구경하지 마.", "저 사람도 나랑 같은 짓 했어.", "나는 억울해요. 정말이에요.", "물 한 모금만.", "너도 곧 여기 올 거야."],
    zooDemonCalls: ["크르르…", "(철창을 긁는다)", "냄새가 나는군. 아래 냄새.", "(이빨을 드러내고 웃는다)", "천국 구경은 재미있나?"],
    homeDeja: ["이 골목, 처음인데 처음이 아니다.", "계단 수를 세지 않았는데 몇 개인지 안다.", "누가 이 길로 나를 업고 내려간 적이 있다. 그런 것 같다."],
    yunaeInAlone: "그네 하나가 비어 있다. 아까부터.",
    yunaeLookAlone: "여자애가 빈 그네를 계속 민다. 노란 머리끈이 손목에 감겨 있다.",
    yunaeTeenAlone: [["…왜 안 와. 그네 맡아 놨는데.", "어른들이 너 이제 안 온대. 거짓말이지?"], ["머리끈 아직 하고 있어. 노란 거.", "너도 하고 있지? 절교 안 했지?"], ["나 혼자 일곱 시 가로등 봤어.", "재미없더라. 네가 없으니까 그냥 불이더라."], ["네 엄마가 오늘 내 얼굴 보더니 울었어.", "나 아무것도 안 했는데."]],
    yunaeTeenWho: ["…누구세요?", "아, 미안해요. 아는 애랑 닮아서요. 그 애는 여자앤데."],
    wombLines: ["따뜻하고 어두웠다.", "누군가 배를 두드리며 노래를 불렀다. 그 목소리를 안다.", "…빛을 보기 전에, 소리가 먼저 멀어졌다."],
    buldaSwing: ["너, 뱃속에서 왔지. 물 냄새가 아직 안 빠졌어.", "누가 널 오래 기다렸다더라. 놀이터 그네 옆자리를 비워 두고.", "그런 자리는 잘 안 없어져. 다음 생에도 남아 있을걸. …비트 들어간다."],
    mariName: "인형술사 마리",
    mariFirst: ["어서 와요. 문은 열어 둬요. 얘들이 바람을 좋아하거든.", "나는 마리. 실을 잇고, 실을 끊어요. 둘 다 같은 손으로 하죠.", "당신 대신 죽어줄 친구가 필요한가요?"],
    mariAgain: ["또 왔네요. 지난번 그 애는 잘 죽어 줬어요?", "쉿. 셋째 선반 애가 자고 있어요.", "당신 대신 죽어줄 친구가 필요한가요?", "실 냄새가 나네요. 누가 당신을 당기고 있어요."],
    mariShop: "인형을 본다",
    mariEyes: "방금… 저 인형이 눈을 굴렸는데요?",
    mariEyesAns: [["봤어요? 그 애는 아직 자기가 사람인 줄 알아요.", "나쁜 애는 아니에요. 그냥 너무 오래 서 있었을 뿐."], ["눈은 내가 붙인 게 아니에요. 처음부터 거기 있었어요.", "누구 눈이었는지는 묻지 말아요."], ["가끔 손님을 따라 봐요. 데려가 달라는 거죠.", "안 돼요. 그 애는 못 팔아요. 아직 값을 다 못 치렀거든."]],
    mariWho: "당신은 누구죠?",
    mariWhoAns: ["위에서는 다들 나를 좋은 사람이라고 했어요. 동네 애들 인형을 공짜로 고쳐 줬으니까.", "고쳐 주면서 실을 한 가닥씩 남겨 뒀죠. 언제든 당길 수 있게.", "여기선 아무도 날 좋은 사람이라고 안 불러요. 그게 편해요."],
