    svcChip: "예배 중 · {t} 남음",
    svcLines: {"church": ["오늘 이 자리에 모인 영혼들을 위하여.", "아래에 두고 온 이름들을 잠시 내려놓으세요.", "빛이 오래 머문 자리는 따뜻합니다.", "용서받았다는 걸 믿는 것도 일입니다.", "함께 일어서지 않아도 됩니다. 마음만 일어서세요.", "(오르간 소리가 천장까지 차오른다)"], "temple": ["숨을 세십시오. 하나, 들이쉬고.", "지나간 생은 연꽃 아래 진흙입니다.", "내려놓은 만큼 가벼워집니다.", "종소리가 끝날 때까지 아무것도 붙잡지 마세요.", "(목탁 소리가 일정하게 이어진다)", "아픈 것도 지나가고, 좋은 것도 지나갑니다."], "mosque": ["평안이 여러분 위에.", "이마를 땅에 대는 자가 하늘에 가장 가깝습니다.", "감사로 시작하고 감사로 마칩니다.", "오늘 받은 것을 하나씩 세어 보십시오.", "(낮은 낭송이 물결처럼 번진다)", "서두르지 마십시오. 여기엔 시간이 넉넉합니다."]},
    svcMurmur: ["(웅얼웅얼)", "…", "아멘…", "(작은 한숨)", "(누군가 코를 훌쩍인다)", "(옆 사람이 꾸벅 존다)"],
    svcBless: {"church": "가십시오. 오늘도 빛 가운데.", "temple": "합장. 오늘의 공덕이 모든 이에게.", "mosque": "평안히 가십시오. 내일 또 뵙겠습니다."},
    svcEnd: "예배가 끝났다. 몸이 조금 가벼워진 것 같다.",
    svcEndYw: "잘 앉아 있었어요. 노을도 봤을 거예요. 아마 칭찬은 안 하겠지만요.",
