    svcOfficiant: "오늘의 예배를 이끄는 천사",
    svcSoulLines: ["쉿. 지금은 듣는 시간이에요.", "처음 오셨어요? 따라 하기만 하면 돼요.", "다리가 저려요… 천국에서도요.", "오백 년째 같은 말씀인데, 오늘은 좀 다르게 들리네요.", "노을 님이 뒤에 서 계시면 졸 수가 없어요."],
    noeulTellTime: "오늘 예배는 {t}. 종이 두 번 울리면 내가 데리러 간다. 숨지 마.",
    noeulDraw: "(스릉 — 칼 뽑는 소리)",
    noeulSheathe: "(칼을 거둔다)",
    noeulProwl: ["…", "(칼끝이 바닥을 긁는다)", "계속해. 듣고 있으니까.", "황색날개, 그런 말에 웃지 마.", "선물은 기록해 둔다.", "부모천사에게 너무 다정한 영혼은 수상하지."],
    ywMenu2: {"praise": "칭찬하기", "present": "선물하기", "angels": "천사들에 대해", "home": "집에 데려다줘요", "back": "천국 거리로 돌아가요"},
    ywPraise: ["날개가 정말 예뻐요.", "목소리를 들으면 마음이 놓여요.", "오늘 머리 모양이 잘 어울려요.", "당신이 제 부모천사라서 다행이에요.", "오백 년 동안 지치지 않았어요?"],
    ywPraiseReply: ["…노란 건 원래 그래요. 그래도 고마워요.", "그럼 말을 조금 더 많이 할게요. 싫다고 하기 없기예요.", "노을이 들으면 혼날 텐데. …그래도 고마워요.", "저도요. 당신이 말을 잘 듣는 영혼은 아니지만요.", "지쳤죠. 그래도 가끔 당신 같은 영혼이 와요. 그래서 버텨요."],
    ywGiveAsk: "저한테요? 무엇을요?",
    ywGiveNone: "가방에 드릴 만한 게 없네요. 마음만 받을게요.",
    ywGiveReply: "{item}… 천국에선 다 공짜인데, 이건 이상하게 소중하네요.",
    ywAngels: ["천사에게도 아홉 품계가 있어요. 위에서부터 치천사, 지천사, 좌천사.", "가운데가 주천사, 역천사, 능천사. 아래가 권천사, 대천사, 천사예요.", "대부분은 제 직책과 함께 부모천사 일을 해요. 영혼 하나를 맡아, 천국의 시간으로 오백 년.", "저는 품계보다 부모천사라는 이름이 더 좋아요. 당신을 맡고 있으니까요.", "노을은 대천사예요. 아래 품계지만 칼은 누구보다 빠르고, 휘두를 때마다 빛이 쏟아져요.", "언젠가 지옥을 거의 다 쓸어버릴 거라는 이야기도 있어요. 노을한텐 비밀이에요."],
    ywHomeFirst: ["구름 위에 당신 몫의 작은 집이 있어요. 부모천사가 맡은 영혼은 다 하나씩 받아요.", "걸어서는 못 가요. 꽉 잡아요."],
