    twinSub: "노을이 맡은 쌍둥이",
    twinBark: ["{sib} 집에 개구리 넣어 놨다!", "쉿, 난이야 저기 온다!", "이 집 창문 우리가 닦아 줬어. 진짜야.", "노을 언니한테 이르면 안 돼!", "구름 아래로 떨어뜨리면 어디로 가?", "{sib} 신발 어디 있게~?", "오늘 예배 때 졸았지? 다 봤다!"],
    twinTalk: [["업이: {sib}! 우리 비밀 하나 알려 줄까?", "난이: 하지 마. 또 노을 언니한테 혼나.", "업이: …{sib} 집 굴뚝에 솔방울 넣었어.", "난이: 세 개."], ["난이: 아래에서 왔지? 아래는 어때?", "업이: 무서운 데래. 칼 든 언니가 맨날 내려가잖아.", "난이: 노을 언니는 무섭지 않아. 화낼 때만 무서워.", "업이: 그게 맨날이잖아."], ["업이: 우리는 노을 언니가 키워. 언니는 대천사야!", "난이: 아래 품계래. 근데 칼은 제일 빨라.", "업이: 지옥 괴물을 한 번에 열 마리 벤대!", "난이: 그건 업이 오빠가 지어낸 거야."], ["난이: 황색날개 언니한테 꽃 줬지? 우리가 다 봤어.", "업이: 노을 언니가 칼 뽑았잖아. 크크.", "난이: 언니는 질투하는 게 아니래. 감시하는 거래.", "업이: 그게 질투야."], ["업이: {sib} 집 이불 우리가 펴 놨어.", "난이: 그 밑에 뭐 있는지는 말 안 할 거야.", "업이: 개구리는 아니야. 이번엔."]],
    twinPrank: ["(쌍둥이가 가방에서 뭔가를 슬쩍 빼 간다!)", "(키득거리며 구름 뒤로 숨는다)"],
