    palaceFind: "찾았어요. 선한 일 {g}, 어긋난 일 {e}, 예배 {r}번. 아직 다 쓰이지 않은 장이네요.",
    palaceAbout: ["영혼마다 책 한 장씩을 여기서 맡아요. 부모천사가 오백 년 동안 그 장을 채우고요.", "저울은 장식이 아니에요. 다 쓴 장은 저기 올려서 무게를 답니다.", "깃털 하나보다 가벼우면… 그건 그때 가서 얘기해요."],
    palaceSvc: "예배는 매일 {t}예요. 종이 두 번 울리면 노을 님이 데리러 가세요. 숨어 봤자 소용없고요.",
