    bedSleep: "잔다",
    bedNoSleep: ["누워 봐도 눈이 감기지 않는다. 이 집은 아직 내 집 같지 않다.", "천장만 본다. 여기서는 잠이 오지 않는다. 호텔이라면 모를까.", "잠이 오지 않는다. 오늘 밤은 호텔 방이 나을지도."],
