    weightTag: "무게 {n}",
    ywShopOpen: "가게 열어 줘요",
    ywShopGreet: ["어서 오세요. 앉을 자리는 없지만 물건은 다 좋은 거예요.", "천국에도 가게는 있어요. 다들 갖고 싶은 게 하나쯤은 남아 있거든요.", "골라 보세요. 칼은 없어요. 여기선 쓸 일이 없잖아요.", "오셨네요. 만나가 오늘 아침에 막 내려왔어요."],
    ywShopNoMoney: "조금 모자라네요. 은행에 가면 꺼내 쓸 수 있어요. 여기선 아무도 세지 않아요.",
