    cbLines: ["또 왔네요? 나를 기억하지 않을 거에요?", "이 세상에서 살기로 결정해주세요. 저와 함께 살아요.", "왜 또 왔어요? 내가 보고 싶었나요?", "제발 그만 나가주세요.", "제발 꺼져요. 못생긴 사람아.", "문 앞에서 한참 서 있었죠? 다 보였어요.", "이번엔 이름을 두고 가요. 그래야 내가 부를 수 있잖아요.", "그냥 구경만 할 거면 나가요. 진심이에요.", "당신 같은 손님이 제일 싫어요. 왔다가, 아무것도 안 정하고, 또 와요.", "보고 싶었다고 하면 믿을 거예요? 거짓말이에요. …조금은.", "이번엔 오래 있다 가요. 아니면 아예 오지 말든가.", "살기로 정하면 그다음부턴 날 잊지 않아요. 그게 규칙이에요.", "웃지 마요. 당신 웃는 거 하나도 안 귀여워요.", "또 그 얼굴이네. 질리지도 않아요?", "왔어요? …반가워서 이러는 거 아니에요.", "다음에도 이름 없이 오면 문 안 열어 줄 거예요.", "한 번만 말할게요. 여기서 살아요. 나랑.", "기억 안 나도 괜찮아요. 내가 기억하고 있으니까.", "나가요. 빨리. …아니에요, 그냥 있어요.", "오늘은 좀 늦었네요. 기다린 건 아니고요."],
    cbReal: ["우주새는 아무나 두 번 오는 데가 아니에요. 세 번째부턴 손님이 아니라 식구죠.", "앵무새가 당신 발소리를 먼저 들어요. 오늘도 그랬어요.", "밖은 덥죠? 여긴 시원해요. 살기로 하면 매일 와도 돼요."],
    cbHell: ["지옥에서 이름도 없이 돌아다니는 건 당신밖에 없어요.", "또 떨어졌어요? 여기까지 와서 망설이는 사람은 처음 봐요.", "유황 냄새 배기 전에 정해요. 여기 사는 건지, 지나가는 건지."],
    cbHeaven: ["천국까지 와서 이름이 없으면 여기서도 당신을 부를 수가 없어요.", "여긴 다 정해진 사람만 와요. 당신만 빼고요.", "날개가 있어도 갈 데를 정하지 않으면 그냥 떠다니는 거예요."],
    cbCount: {"2": "두 번째네요. 한 번은 실수, 두 번은 버릇이래요.", "3": "세 번째. 이 정도면 나 보러 오는 거죠?", "5": "다섯 번째예요. 손가락을 다 썼어요.", "7": "일곱 번째. 행운의 숫자라던데, 당신한텐 아닌 것 같네요.", "10": "열 번째예요. 이제 그냥 여기 살아요.", "20": "스무 번. 세는 것도 지겨워요. …그래도 셌어요."},
    cbNth: "{n}번째예요. 세고 있었어요. 아무한테도 말하지 마세요.",
    cbLive: "이 세상에서 살기로 결정한다",
    cbJustLook: "그냥 둘러볼게요",
    cbHangUp: "끊는다",
    cbYes: ["…진작 그럴 것이지.", "좋아요. 이름부터 알려 줘요.", "그 말 기다렸어요. 아주 조금."],
    cbNo: ["그래요. 마음대로 해요.", "알았어요. 어차피 또 올 거잖아요.", "흥. 물건이나 봐요.", "그럼 조용히 보고 가요."],
    callMember: ["잘 있어요? 그냥요. 목소리 들으려고요.", "오늘 누구 때렸어요? …아니에요. 묻지 않을게요.", "거긴 비 와요? 여긴 안 와요. 가게 안이라서요.", "지갑은 괜찮아요? 은행에 넣어 두는 거 잊지 말아요.", "아까 가게 앞 지나갔죠. 들어오지도 않고.", "앵무새가 당신 이름을 불렀어요. 가르쳐 준 적 없는데.", "바쁘면 받지 말지 그랬어요.", "아무 일 없어요. 그냥, 한 시간쯤 됐길래."],
    callMemberHell: ["몇 층이에요? 너무 내려가지 마요. 거긴 전화가 안 돼요.", "노전은 아껴 써요. 여긴 빌려주는 사람이 무섭거든요.", "불 냄새 나요. 거기도 덥죠."],
