    offPuzzled: "…จะเกิดใหม่งั้นหรือ? (ลูเอนวางตะเกียงลง แล้วจ้องมองคุณอยู่นาน) ขอโทษที ไม่ได้ยินคำนี้ที่นี่มานานมากแล้ว",
    offPleas: [["ที่นี่ไม่มีใครหิว ไม่มีหนี้ ไม่มีวันจ่ายค่าเช่า ไม่มีใครมาเคาะประตู ทุกอย่างที่เคยอยากได้มาทั้งชีวิตมีอยู่เหมือนอากาศ", "ลืมไปแล้วหรือว่าข้างล่างเป็นอย่างไร? นายจ้างที่โกงค่าแรงแล้วไล่ออก รถที่บีบแตรด่าเมื่อเราขวางทาง นั่นคืออากาศของข้างล่าง"], ["แล้วครั้งนี้ก็แค่โชคดี มือไม่เปื้อนจึงได้มาถึงที่นี่ ใครจะรับประกันว่าชาติหน้าจะเป็นแบบนี้อีก", "ลงไปแล้วต้องทิ้งทั้งความทรงจำและความดีที่สะสมไว้ มือเปล่า เริ่มใหม่ทั้งหมด พลาดเพียงครั้งเดียว ประตูจะไม่เปิดขึ้นข้างบน แต่จะเปิดลงข้างล่าง"], ["พูดตรงๆ เลยนะ การเกิดใหม่จากสวรรค์ไม่ใช่รางวัล แต่คือการถูกลดชั้น ที่ให้ได้มีแค่ค่าของกรรมดีไม่กี่เหรียญ ที่เหลือต้องทิ้งไว้ทั้งหมด", "มันคือการเตะทิ้งสิ่งที่ปีนขึ้นมาถึงด้วยตัวเอง ในบรรดาวิญญาณที่ข้าส่งลงไป คนที่ไม่เสียใจเลย… นึกไม่ออกสักคน"]],
