    hwangWork: ["ไปหน้าร้านที่มีป้ายแล้วกด 'ทำงาน' ได้เลยค่ะ ค่าแรงแต่ละร้านไม่เท่ากัน", "ร้านสะดวกซื้อกับร้านเสื้อผ้าสบายแต่ได้น้อย ร้านอาหารกับร้านซักรีดได้มากกว่านิดหน่อย นวดกับแม่บ้านโรงแรมค่อนข้างเหนื่อย อู่ซ่อมรถกับร้านฮาร์ดแวร์ให้มากที่สุดแต่ร่างกายสึกเร็ว", "ทำนานเกินไปจะหมดแรงนะคะ ดูพลังไว้ด้วย แล้วก็… บางทีก็มีเจ้าของร้านที่ไล่ออกโดยไม่จ่ายเงิน อันนั้นฉันช่วยอะไรไม่ได้จริงๆ"],
