    ywRebirthPleas: ["ข้างล่างหิว เงินไม่พอ ร่างกายเจ็บ ที่นี่ไม่มีสักอย่าง", "ถ้าเกิดใหม่ ความทรงจำตอนนี้ต้องทิ้งไว้หมด รวมถึงฉันด้วย คุณจะลืมฉันนะคะ", "คนที่คลานขึ้นมาจากนรกมีตั้งเท่าไหร่ อย่าพูดแบบนี้ต่อหน้าพวกเขานะ", "คุณทำดีมาทั้งชีวิตเพื่อมาที่นี่ จะเอามันไปเสี่ยงอีกรอบเหรอ", "โลกข้างล่างรอบหน้าอาจไม่เข้าข้างคุณก็ได้", "การเกิดใหม่ไม่ใช่รางวัล มันคือการสอบใหม่ตั้งแต่ต้น", "ดูคนที่นอนข้างทางพวกนั้นสิ ไม่มีใครกังวลเลย นั่นแหละที่นี่", "อาหารฟรี ที่นอนฟรี ฟ้าใสตลอด ยังขาดอะไรอีก", "มีใครรออยู่ข้างล่างเหรอ? …สักวันเขาก็ขึ้นมาที่นี่ รอก็พอ", "พูดตรงๆ นะคะ ถ้าวิญญาณที่ฉันดูแลลงไป มันจะติดอยู่ในประวัติฉัน ไม่ใช่ในทางที่ดี", "คิดอีกสักรอบ ไม่สิ อีกสิบรอบ", "อยากกลับไปมีร่างไร้ปีก ขึ้นรถเมล์ จ่ายค่าเช่า ต่อคิวอีกเหรอ", "เกิดใหม่จากสวรรค์ไม่มีของแถมนะคะ ตัวเปล่า ตัวเปล่าจริงๆ"],
    ywRebirthEnd: "…ถ้ายังไม่เปลี่ยนใจ ไปหาลูเอนนะคะ ท่านจะห้ามเป็นครั้งสุดท้าย ท่านห้ามเก่งกว่าฉันเยอะ",
    ywLuenHere: "ลูเอนอยู่บนระเบียงแห่งการเกิดใหม่ เหนือบันไดเมฆที่ขอบเมฆสุดเขตนี้ค่ะ เลยไปจะเห็นหอคอย — ที่นั่นยังไม่มีใครไปได้ ฉันทำเครื่องหมายสีทองไว้ให้นะคะ …ไม่ได้จะไปจริงๆ ใช่ไหม",
    ywLuenFar: "ลูเอนอยู่สุดแผนที่ค่ะ ปลายสุดทางตะวันออก พร้อมพงษ์ บนบันไดเมฆที่ขอบเมฆ จากตรงนี้ไป{dir}",
    ywRules: ["กฎของสวรรค์ ขอบอกแค่สามข้อนะคะ", "หนึ่ง ต้องไปพิธีทางศาสนา จะวัด โบสถ์ หรือมัสยิดก็ตาม ถ้าเทวดาหน้าประตูเรียก ก็เข้าไป", "สอง ที่นี่ไม่มีใครบาดเจ็บ วิญญาณที่ลงมือทำร้ายจะตกลงไปข้างล่างทันที", "สาม ถ้ามนุษย์รักเทวดา คนที่โดนลงโทษคือเทวดา เบาๆ ก็เสียปีก หนักๆ ก็… หายไปเลย", "เพราะฉะนั้นอย่าดีกับฉันมากนักนะคะ พูดจริงๆ", "อ้อ สวรรค์ก็อยู่บนพื้นดินเหมือนกัน ถ้าจะไปเมืองอื่น ให้หาเทวดาแท็กซี่ที่สุดปลายเมือง"],
    ywAlone: "ยังไม่เคยไปพิธีสักครั้งเลยนะคะ ก่อนหน้านั้นปล่อยไม่ได้หรอก",
    ywFollowAgain: "ถ้าหนีอีกล่ะก็ คราวนี้ไม่ตามจริงๆ นะ …มั้ง",
    ywAdapted: "ไปพิธีมาแล้วสินะคะ เก่งมาก แต่ทุกครั้งที่มาสวรรค์ ฉันจะอยู่ข้างๆ นะคะ ถ้าอยากอยู่คนเดียวก็บอกได้",
    admireToF: ["ขอโทษนะครับ… คุณสวยมากเลย", "ไปกินข้าวกับผมสักมื้อไหมครับ ที่นี่ฟรีหมด", "พรุ่งนี้เจอกันอีกได้ไหมครับ", "แต่งงานกับผมเถอะครับ ผมจริงจังนะ ที่นี่เวลาเยอะ", "ตอนอยู่ข้างล่างก็สวยขนาดนี้เลยเหรอครับ", "เมฆลอยไปทางคุณหมดเลยนะครับ"],
    admireToM: ["ตายแล้ว หล่อมากเลยค่ะ…", "ไปกินข้าวด้วยกันไหมคะ ฉันรู้จักร้านดีๆ", "พรุ่งนี้เจอกันนะคะ หน้าร้านอูจูแซ", "ถ้าขอแต่งงานจะตกใจไหมคะ", "ตอนอยู่ข้างล่างก็หล่อแบบนี้เลยเหรอ", "แป๊บนึงนะคะ ขอเดินข้างๆ หน่อย"],
    admireBye: ["…ลองคิดดูนะ ฉันมาแถวนี้บ่อย", "คราวหน้าตอบด้วยนะ!", "น่าเสียดาย ไว้เจอกันใหม่"],
