    buldaRaps: ["ทอดแหไป ได้ปลาครึ่ง ขยะครึ่ง\nคนที่หันหลังให้ประตูสวรรค์อีกครึ่ง\nคลื่นซัดมาถามว่า แกเป็นใคร\nฉันไม่ตอบ แค่เก็บแห วันหนึ่งก็ผ่านไป", "กรรมศูนย์ ตาชั่งราบเรียบ\nไม่ดีไม่ชั่ว ทิ้งตัวลงบนทราย\nตรัสรู้เหรอ มันก็เหมือนตกปลา รสของการรอ\nปลาไม่กินเหยื่อแล้วโมโห วันนั้นก็เจ๊ง", "เทียนที่ดับตั้งแต่เพิ่งจุด\nเสียงแรกที่ได้ยินที่นี่คือเสียงฉัน\nขอโทษนะ ที่มันไม่ใช่เพลงกล่อมนอน\nแต่จังหวะน่ะให้ได้ ตามเสียงคลื่นนี่แหละ"],
