    cbLines: ["มาอีกแล้วเหรอ จะไม่จำฉันเลยใช่ไหม", "ตัดสินใจอยู่ในโลกนี้เถอะ อยู่กับฉัน", "มาอีกทำไม คิดถึงฉันเหรอ", "ได้โปรด ออกไปเถอะ", "ไปให้พ้นเลย คนขี้เหร่", "ยืนอยู่หน้าประตูตั้งนานใช่ไหม เห็นหมดแหละ", "คราวนี้ทิ้งชื่อไว้ด้วย ฉันจะได้เรียกถูก", "ถ้าแค่มาดูเฉย ๆ ก็ออกไป พูดจริงนะ", "ลูกค้าแบบคุณน่ารำคาญที่สุด มาแล้วไม่ตัดสินใจอะไร แล้วก็มาอีก", "ถ้าบอกว่าคิดถึงจะเชื่อไหม โกหกน่ะ …นิดหน่อย", "คราวนี้อยู่นาน ๆ หน่อย ไม่งั้นก็ไม่ต้องมาเลย", "ถ้าตัดสินใจอยู่ ต่อไปจะไม่ลืมฉันอีก นั่นคือกฎ", "อย่ายิ้ม ยิ้มแล้วไม่น่ารักเลยสักนิด", "หน้านี้อีกแล้ว ไม่เบื่อบ้างเหรอ", "มาแล้วเหรอ …ไม่ได้ดีใจหรอกนะ", "ถ้าคราวหน้ามาแบบไม่มีชื่ออีก จะไม่เปิดประตูให้", "จะพูดครั้งเดียว อยู่ที่นี่ อยู่กับฉัน", "จำไม่ได้ก็ไม่เป็นไร ฉันจำแทนให้", "ออกไป เร็ว …ไม่ใช่ อยู่ต่อเถอะ", "วันนี้มาช้าหน่อยนะ ไม่ได้รอหรอก"],
