    soulLines: ["I stopped counting which life this is.", "Wake me if the upper gate opens.", "Don't eat the meat here. ...Well, if you're hungry, eat.", "Miss the real world? It scares me.", "They say that one has come down thirty times.", "I'll save obols and go up someday. Someday.", "Hwanghon always has the same face. Only we change."],
    soulLieLines: ["...Let me lie here a little longer.", "(No answer. Still breathing.)", "If I get up I'll have to fight again.", "I dreamed of the sea. The real sea."],
    fighterLines: ["Saving obols to go up. Coming with me?", "No one takes a floor lord alone. Go in numbers.", "If you're hurt, come back to the village. Inside, the wardens are on our side.", "This life, I'm getting out."],
    fighterShout: ["There!", "Come on!", "Obols!"],
    butcherLook: "A blood-soaked apron. The knife never rests. The hanging meat still steams.",
