    bankSign: "BANK",
    bankFind: "Nearest bank (deposit so your money survives death)",
    bankNone: "No bank in this district. Try the next one.",
    xchName: "Obolo the Changer",
    xchSub: "Floor 142 · red devil who turns living money into obols",
    xchGreet: ["(A red tail sweeps across the floor.) Brought living money, did you? Down here it's scrap paper. I'll take it anyway.", "Welcome, fallen guest. Your bank account is still up there, yes? I'll turn it into obols. A little."],
    xchRule: "Your account holds {b}. You're a floor-{f} soul, so you get {f} parts in 13 — up to {p}% of the account. The rate is {r} per obol. The fee is three-tenths of what you change plus {c}, taken from the account.",
    xchOpt: "{a} → {n} obols (fee {f})",
    xchQuit: "Never mind",
    xchPoor: "Not even one obol's worth. You need enough for the fee too. Only now realizing living money is paper?",
    xchUsedUp: "You've used up this trip's share. Come back when your karma's heavier.",
    xchDone: "(Coins jingle.) {n} obols. {a} of living money shrank to this. The fee of {f} is mine.",
    xchBye: ["Drop by when you fall again.", "Money isn't for saving. It's for carrying down."],
    xchIdle: ["Exchange, exchange… living money taken.", "Scrap paper accepted.", "Honestly expensive fees."],
    gkChanger: "Done? Out that door. You'll fall. Living money goes to the red one. He'll take nearly all of it.",
    lobbyXRule: "You hold {o} obols, counting your hand. Your karma earns floor {f} of 13, so only {p}% can become next-life money. Up there an obol is scrap metal — {r} each. The fee is three-tenths of what you change plus {c} obols.",
    lobbyXOpt: "{n} obols → {a} (fee {f})",
    lobbyXNone: "Don't change (obols stay in the hell bank)",
    lobbyXPoor: "After the fee there'd be nothing left. Go empty-handed. Your obols stay in the hell bank.",
    lobbyNoCity: "Evil 100%. I can't let you choose where you're born.",
    lobbyCarry2: "{n} obols became {a} in your hand.",
    offBonus: "Your good deeds this life: {g}. On your way down I'll press {a} of living money into your hand. The price of good deeds. …Money you wouldn't need if you stayed.",
    offBonusNone: "No good deeds yet… nothing to give you.",
    grandpaBonus: "(The old man rummages in his pocket.) Take what your good deeds earned. {a}.",
    heavenBonusToast: "Born with {a}, the price of good deeds.",
    repairAll: "Repair all · {n} items · {p}",
    repairAllDone: "Repaired all {n} items.",
    asmTitle: "Assemble a Tembra",
    asmLine: "Fit the shards into the frame one by one. Thirteen make one Tembra. (shards {s} · Tembra {t})",
    asmPut: "Fit a shard ({n}/13)",
    asmNone: "No shards to fit. Hell's monsters drop them rarely.",
    asmPick: "Choose gear to use the Tembra on",
    enhRule: "+1 to +3 always succeed. From +4 it gets harder, and from +6 it is very rare. Every 3 levels (+3·+6·+9·+12·+15) attacks get slightly faster. On failure the gear stays (only the Tembra is lost). Hell gear only, up to +15.",
    enhNoTem2: "No Tembra. Fit thirteen shards into the frame above first.",
    tembraMade2: "The thirteenth shard clicks into place. One Tembra.",
    xchOptNeed: "Can't exchange · 1 obol needs {a}+ in the bank",
    xchOptUsed: "Can't exchange · this trip's share is used up",
    lobbyLeave: "I'll come back later (leave)",
    lobbyLater: "The window doesn't close. You'll have to queue again, though.",
    nlCancel: "Stop the consultation",
    nlCancelled: "You stopped the consultation. Nothing was decided.",
    yunaePlace: ["Playground", "Neighborhood salon", "Exam room"],
    yunaeIn: [["You opened the gate. Instead of the room, there was a playground at dusk.", "Over the threshold, the smell of sand. A playground."], ["You opened the gate. Scissors, a hair dryer. The neighborhood salon.", "The door opened on a gust of shampoo. This wasn't home."], ["You opened the gate. The smell of disinfectant. A white exam room.", "The fluorescent light flickered once. An exam room. Someone was looking this way."]],
    yunaeBub: [["…Is it almost seven.", "Hm, hmm-hm.", "Push me."], ["Tell me if it's too hot.", "Just a little more.", "…What time is it."], ["……", "It's all right.", "Why isn't the doctor coming."]],
