    cageLostEach: "Lost item · {p} each",
    hellDeathItem2: "You also dropped your {item}. If no one picks it up it goes to the Sulphur Bird cage (half its price to get back).",
    hellWashed: "The tenth fall. A layer of the sins clinging to you washes away. You drift upward — you wake on floor {n}.",
    hellWashCount: "Fall {k}/{m} on this floor — at {m} your sins wash off and you wake a floor higher.",
    hellNoWash1: "On floor 1 falling washes nothing away. To be reborn you must bring down the floor lord.",
    hellWashBtn: "Wake on floor {n}",
    lobbyNeedBoss: "Turn back. The road to rebirth opens only for those who have seen {boss} fall. Money and offerings mean nothing here.",
    atoneNeedBoss: "Your offering is complete. Still, the gate of floor 1 opens only when the floor lord falls.",
    bossShout: {"ashgal": ["(The gate bar comes crashing down)", "(It charges, kicking up ash)", "(Embers spread in a ring underfoot)", "(Chains of fire coil round you and drag you in)", "(The ground splits and pillars of fire rise)", "(The giant leaps skyward)", "Rise, dead of the threshold.", "(Burning ash pours down like a falling sky)"]},
    bossRage: {"ashgal": "No one has ever gone back from here. Neither will you."},
    lairFieldSub1: "The last gate before rebirth — the only way through is to bring it down",
    civHit: ["How's that feel?", "Want another?", "Awake now?", "See? I can hit too.", "Who started this again?", "Thought that would be the end of it?"],
    civHurt: ["Agh… you serious?!", "My nose is bleeding!", "Ah, you lunatic…", "Stop! I said stop!", "Someone break this up!", "That all you've got?"],
    crookHit: ["We're not done.", "Get down.", "Feel like opening that wallet yet?", "That's how we say hello in this soi.", "I told you to keep your eyes down.", "Try that one more time."],
    crookHurt: ["You little…", "Not bad.", "You're not going home tonight.", "Now there's blood. Now it's real.", "Boys! Over here!", "Where did you learn to punch like that?"],
    barkHitG: {"drunk": ["Hah, got you!", "I'm not usually like this…", "One more drink, then round two."], "robber": ["I told you to keep quiet.", "Next time it's the knife.", "Just drop the bag."], "mafia": ["The boss sends his regards.", "This is just the interest.", "You should have listened when I was polite."], "boxer": ["Elbows hurt, huh?", "Guard up.", "One more round."], "enforcer": ["Kneel for the boss.", "Should have listened while we were talking.", "You're paying the hospital bill."], "thug": ["Where did you crawl out from?", "First time in this soi?"]},
    barkHurtG: {"drunk": ["Ugh, that sobered me up.", "Why you doin' this, man…", "The world is spinning…"], "robber": ["…Don't make noise.", "Damn, did you see my face?", "Let's finish this."], "mafia": ["You ripped my suit.", "What's your name? I want to remember it.", "This goes up the chain."], "boxer": ["Good. Now it's fun.", "Where did you learn that punch?", "Let me catch my breath."], "enforcer": ["…Call the boys.", "You'll pay dearly for this.", "Don't make me laugh."], "thug": ["I'm telling the boss.", "Ah, now I'm angry."]},
    thugTaunt45: ["Got a light?", "You bumped my shoulder. No sorry?", "Lend me your phone a sec.", "Where do you live?", "Walking alone this late? Risky."],
    drunkTaunt45: ["Hey… you know me, right?", "Buy me a drink.", "What're you glaring at, huh?"],
    robberTaunt45: ["Don't turn around.", "Slowly. Hands out of your pockets."],
    mafiaTaunt45: ["Got time for a smoke?", "Heard you drank at our place and skipped the bill."],
    tembraUseTitle: "Use Tembra",
    tembraUseLine: "No need to walk to the forge. Hammer it right here.",
