    trainCapped: "Your body won't take any more today. Come back tomorrow.",
    crusadeAskBtn: "About the march on hell",
    noeulArmoryBtn: "Choose heavenly arms",
    noeulBye: "I'll be going",
    crusadeOffer: "I'm going to march on hell and take the head of the Abyss's master. Will you come with me?",
    crusadeJoin: "I'm in",
    crusadeRulesBtn: "How does it work?",
    crusadeLater: "Not yet",
    crusadeLaterLine: ["If you're scared, stay here. Pray or something.", "Come back when you have made up your mind."],
    crusadeRules: ["You pick the floor. I cut beside you.", "Down there nothing heals. Hell's medicine or heaven's, none of it works.", "Only heavenly weapons will stay in your hand. Theirs slip right out.", "Fall once and it's over. Then I'll carry you up.", "Whatever you pick up goes to the Sulphur Bird's cage. Tell me whenever you want to go back."],
    crusadeFloor: "Hell floor {n} · {name}",
    crusadeNoWeapon: "Bare-handed? …You might want to visit the armory first.",
    crusadeGo: "Floor {n}. Stay close under my wings.",
    noeulArmory: "Armory of Heaven",
    noeulArmoryLine: "They hold only in heaven and on the march. Take them to the living world and they are just scrap.",
    crusadeHi: ["I watch my back. Yours too.", "Let's go. This is no place to linger.", "Don't stop to breathe. This is no place to rest."],
    crusadeNoeulSub: "Watcher of heaven's faith · fights beside you (talk to her to go back)",
    crusadeNoeulDown: ["…Just took a knee.", "One moment. I'll be right up."],
    crusadeNoeulUp: ["Going again.", "It's not over yet."],
    crusadeMid: ["Going back?", "Still holding up?", "It gets deeper ahead."],
    crusadeReturn: "Let's go back to heaven",
    crusadeStay: "Fight a little longer",
    crusadeReturnLine: "Fine. Take my hand.",
    crusadeFallToast: "You fall — Noeul lifts you and takes to the air.",
    crusadeFellLine: "You're still breathing. Next time, don't stray outside my blade's reach.",
    crusadeBackLine: "You held up well. The smell from down there is still in your clothes.",
    crusadeSumKills: "Brought down: {n}.",
    crusadeSumExp: "Soul EXP +{n}.",
    crusadeSumNotes: "The {n} obols you picked up are in the hell bank.",
    crusadeSumItems: "Sent to the Sulphur Bird cage: {list}.",
    crusadeSumNoItems: "You brought nothing back.",
    crusadeNoHeal: "On the march, nothing heals your wounds.",
    crusadeStayFloor: "Noeul: \"This floor this time. Don't wander off.\"",
    crusadeAtk: ["That one.", "Right side's mine.", "Head down.", "In heaven's name."],
    targetLabel: "Target",
    targetTitle: "Switch target (PC: Tab · right-click overlapped enemies; tap the same spot again for the one behind)",
    targetNone: "No enemy nearby.",
