    airportAsk: ["The airport is just past here. There are flights to Seoul.", "The airport is just past here. There are flights to Bangkok."],
    airportGo: "Go to the airport",
    airportName: "Airport departures",
    airportArrive: "Departures · buy a ticket at the counter, then go to immigration",
    airportClerk: "Airline clerk",
    ticketAsk: ["One way to Seoul Incheon, {p}. Window seat?", "One way to Bangkok Suvarnabhumi, {p}. Window seat?"],
    ticketBuy: "Buy the ticket · {p}",
    ticketShort: "You're a little short. Maybe stop by a bank?",
    ticketDone: "Here is your boarding pass. Immigration is on the right. Have a good trip.",
    ticketHave: "You already have a ticket. Immigration is on the right.",
    immigNoTicket: "The officer shakes his head — get a ticket first",
    immigOfficer: "Immigration officer",
    immigLines: ["Passport. …Let me see your face.", "You look a little different from the photo. Well, everyone does.", "(Thump of a stamp) Next."],
    flightLine: ["Clouds drift past the window. It feels like there are roads up there too.", "Clouds drift past the window. Somewhere down there was a sunflower field."],
    landed: ["Landed in Seoul. The air is cold.", "Landed in Bangkok. The heat steals your breath."],
