    // 48차 (자동)
    weightTag: "wt {n}",
    ywShopOpen: "Open your shop for me",
    ywShopGreet: ["Welcome. There's nowhere to sit, but everything here is good.", "Heaven has shops too. Everyone still wants something.", "Have a look. No blades — you won't need them here.", "You came. The manna only fell this morning."],
    ywShopNoMoney: "A little short. The bank will give you more. Nobody counts here.",
    ywShopPickGoods: "{item}? Take your time with it.",
    ywShopPickArmor: "{item}? It'll suit you. You know it can only be worn here?",
    ywCageLines: ["......", "Nothing to keep here.", "Nothing gets lost in heaven. So there is nothing to keep."],
    ywShopName: "Yellow Wing's shop",
    ammoUnits: "{n} rounds",
    ammoNeedBow: "You need a bow in hand to nock arrows",
    ammoNeedGun: "You need the right gun in hand to load these",
    cbLines: ["Back again? You still won't remember me?", "Decide to live in this world. Live with me.", "Why are you back? Did you miss me?", "Please, just leave.", "Get lost. You ugly thing.", "You stood at the door for a long time, didn't you? I saw.", "Leave your name this time. Then I can call you.", "If you're only looking, get out. I mean it.", "I hate customers like you. You come, decide nothing, and come again.", "If I said I missed you, would you believe it? A lie. …Mostly.", "Stay longer this time. Or don't come at all.", "Once you decide to live here, you won't forget me again. That's the rule.", "Don't smile. It isn't cute at all.", "That face again. Aren't you tired of it?", "You came? …I'm not glad, if that's what you think.", "Come without a name again and I won't open the door.", "I'll say it once. Live here. With me.", "It's fine if you don't remember. I remember for you.", "Go. Quickly. …No. Stay.", "You're late today. Not that I was waiting."],
    cbReal: ["Nobody comes to the Cosmic Bird twice by accident. By the third time you're family, not a customer.", "The parrot hears your footsteps first. It did today too.", "Hot outside? It's cool in here. Decide to live, and you can come every day."],
    cbHell: ["You're the only one wandering hell without a name.", "Fell again? I've never seen anyone come this far and still hesitate.", "Decide before the sulphur gets into your clothes. Living here, or passing through."],
    cbHeaven: ["Even in heaven, without a name, no one here can call you.", "Everyone here has decided. Everyone but you.", "Even with wings, if you don't choose where to go, you only drift."],
    cbCount: {"2": "The second time. Once is a mistake, twice is a habit.", "3": "Third time. You're coming to see me, aren't you?", "5": "Fifth. I've run out of fingers on one hand.", "7": "Seventh. A lucky number, they say. Not for you.", "10": "The tenth time. Just live here.", "20": "Twenty. I'm tired of counting. …I counted anyway."},
    cbNth: "That's {n} times. I've been counting. Don't tell anyone.",
    cbLive: "Decide to live in this world",
    cbJustLook: "Just looking",
    cbHangUp: "Hang up",
    cbYes: ["…You should have done that long ago.", "Good. Your name first.", "I was waiting for that. A little."],
    cbNo: ["Fine. Suit yourself.", "All right. You'll be back anyway.", "Hmph. Look at the goods, then.", "Then look quietly and go."],
    callMember: ["Are you all right? Nothing. I just wanted to hear your voice.", "Who did you hit today? …No. I won't ask.", "Is it raining there? Not here. I'm inside the shop.", "How's your wallet? Don't forget the bank.", "You walked past the shop earlier. Didn't come in.", "The parrot said your name. I never taught it.", "If you were busy, you didn't have to answer.", "Nothing's wrong. It's just been about an hour."],
    callMemberHell: ["Which floor? Don't go too deep. Calls don't reach down there.", "Go easy with your obols. The lenders here are frightening.", "I can smell the fire. It's hot there too, isn't it?"],
    callHangup: ["I'll hang up.", "…I called because I didn't want to hang up. Now I will.", "I'll call again next hour."],
    callMissed: ["One missed call.", "The call ended. It does not ring again."],
    ywHourly: ["Found you. I have to see you once an hour or I can't settle.", "The other angels say you've been walking alone too much lately.", "Need anything? I can open the shop for you.", "Don't tell Noeul I came.", "Did you look at the sky today? It's so different from how it looks below."],
    ywHourlyBye: "I'm fine",
    ywHourlyEnd: ["Then I'll come again. In an hour.", "Don't go far.", "All right. I'll fold my wings and wait."],
    collector: "Loan-shark collector",
    collectorSub: "Here for interest on money you never borrowed",
    collectorLook: "A gold chain glints through a white shirt open two buttons. The end of an iron pipe taps his palm slowly. He smiles, but his eyes are reading a ledger.",
    collectorLines: ["Time to pay back what you borrowed.", "The boss says hello.", "Interest grows today too."],
    collectorTaunt: ["Your name is in the ledger.", "Run, and the interest follows.", "Just the interest today. Not the principal."],
    collectorDemand: ["Wallet out. Slowly.", "This month's share, please."],
    collectorGiveUp: ["I'll be back next week.", "It stays in the ledger."],
    collectorInterest: ["Interest.", "Late fee.", "And a handling charge."],
